{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Adaptation & Load Management",
      "weeks": 3,
      "focus": "Re-establish technical lifts with pregnancy-safe modifications and submaximal loading"
    },
    {
      "name": "Strength Development (Submaximal)",
      "weeks": 5,
      "focus": "Progress compound strength with conservative intensity, emphasis on posterior chain and pelvic stability"
    },
    {
      "name": "Strength Maintenance & Durability",
      "weeks": 4,
      "focus": "Maintain strength, increase movement variety, prioritize breathing/positioning and readiness for late pregnancy"
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Lower heavy (submaximal)",
      "Upper heavy (submaximal)",
      "Active recovery & core + pelvic floor",
      "Full-body metabolic strength (controlled)"
    ]
  },
  "non_negotiables": [
    "No supine after week 16",
    "No max attempts",
    "No contact sports",
    "OB cleared for moderate strength (follow medical clearance)",
    "Avoid Valsalva that produces dizziness or excessive breath-holding; prioritize controlled breathing",
    "Progress loads conservatively; stop or lower load with any dizziness, bleeding, sharp pain, leakage, or unusual fetal movement changes"
  ]
}
